import { Injectable } from '@angular/core';
import { CaseDetailResponce, CaseRequestMdl, CaseResponce } from '../../interfaces/casebuilder.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { firstValueFrom } from 'rxjs';
import { HttpClient, HttpParams } from '@angular/common/http';
import { environment } from '../../../../environments/environment';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';

@Injectable({
  providedIn: 'root'
})
export class CaseBuilderService {

  constructor(
    public readonly sStore: SecureStorageService,
    private readonly http: HttpClient,
    public readonly tost: TostbarService
  ) { }
  
  async caseBuilder(mdl: CaseRequestMdl): Promise<CaseResponce> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<CaseResponce>(`${environment.cloudUrl}${environment.coreservice}/case/casebuilder`, mdl)
      );
      if (res?.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err: unknown) {
      this.tost.openSnackBar(`Case creation failed ${ErrorHandlerUtil.getErrorMessage(err)}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }

  async getCaseDetail(nCaseid: string): Promise<CaseDetailResponce> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<CaseDetailResponce>(
          `${environment.cloudUrl}${environment.coreservice}/case/casedetail`,
          { params: params }
        )
      );

      return res;
    } catch (err: unknown) {
      console.error(`Failed to get case detail: ${ErrorHandlerUtil.getErrorMessage(err)}`);
      return {};
    }
  }

  async caseDelete(nCaseid: string): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<CaseResponce>(`${environment.cloudUrl}${environment.coreservice}/case/casedelete`, { nCaseid: nCaseid })
      );
      if (res?.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err: unknown) {
      this.tost.openSnackBar(`Case delete failed ${ErrorHandlerUtil.getErrorMessage(err)}`, 'E');
      return false;
    }
  }

  async updateCaseTuples(nCaseid: string): Promise<CaseResponce> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<CaseResponce>(`${environment.cloudUrl2}${environment.realtimeserive}/case-tuple/updates`, { nCaseid: nCaseid })
      );
      if (res?.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err: unknown) {
      this.tost.openSnackBar(`Case creation failed ${ErrorHandlerUtil.getErrorMessage(err)}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }
}
